echo "--- checks"; grep -o 'og:type" content="[a-z]*"' dist/articles/hello-narration/index.html; grep -o 'audio data-narration[^>]*src="[^"]*"' dist/articles/hello-narration/index.html; cat dist/rss.xml; echo; grep -o '[^<>]*articles[^<>]*' dist/sitemap-0.xml; echo "--- markdown twin"; cat dist/articles/hello-narration.md; pnpm exec tsc --noEmit -p . 2>&1 | tail -3; ls src/lib; grep -n '"test"' package.json
sed -i '' 's/^draft: false$/draft: true/' src/content/articles/hello-narration.md

